fun main(){var n=0;fun t(x:Boolean){check(x){"Assertion ${n+1}"};n++}
 t(Batch17.upcoming(5,1){it+1}==listOf(2,3,4));t(Batch17.upcoming(5,1){mapOf(1 to 4,4 to 0,0 to 1)[it]?:-1}==listOf(4,0));t(Batch17.upcoming(0,0){0}.isEmpty());t(Batch17.queueOrder(5,3){it+1}==listOf(3,4,0,1,2));t(Batch17.queueOrder(2,-1){0}==listOf(0,1));t(Batch17.nextPosition(0,2,4)==2);t(Batch17.nextPosition(3,1,4)==2);t(Batch17.nextPosition(1,1,4)==null);t(Batch17.nextPosition(-1,1,4)==null);t(Batch17.isVersion("A Song","A Song (Official Video)"));t(Batch17.isVersion("A Song (Live)","A Song Remix"));t(!Batch17.isVersion("A Song","Another A Song"));t(!Batch17.isVersion("A Song","A Song For You"));t(!Batch17.isVersion("",""));t(Batch17.isVersion("गाना","गाना live"));t(Batch17.related("A",listOf(listOf("A","B","C"),listOf("A","B"),listOf("C"),listOf("C")))==listOf("B","C"));t(Batch17.related("a",listOf(listOf("A","B","B"),listOf("A","c")))==listOf("B","c"));t(Batch17.related("z",listOf(listOf("A","B"))).isEmpty());t(Batch16.alternate("abcdefghijk","A Song",listOf("abcdefghijk" to "A Song", "abcdefghijx" to "A Song remix", "abcdefghijy" to "A Song For You"))==listOf("abcdefghijx"));val seed=Song("seed","Title","Artist","","");val a=Song("a","A","Artist","","");val b=Song("b","B","Related","","");val c=Song("c","C","Unrelated","","");t(Batch17.radio(seed,listOf(a,b,c,a,seed),listOf("Related"),emptySet()).map{it.id}==listOf("a","b"));t(Batch17.radio(seed,listOf(a,b),listOf("Related"),setOf("a")).map{it.id}==listOf("b"));t(Batch17.radio(seed,listOf(a.copy(live=true),c),emptyList(),emptySet()).isEmpty());println("$n V17 core assertions passed")}
